/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: mount, paneTone, settle, pointerOver
 *   Constants: sample, red, blue
 *   Variables: nextId
 * Tests
 *   - starts neutral, follows the hovered card, and returns to neutral after leaving the cards
 *   - follows keyboard focus and keeps the focused card tone after the pointer leaves
 *   - ignores touch pointers and a tone that resolves after the pointer moved on
 *   - clears the main-pane tone on unmount and ignores samples that finish afterwards
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';

import { sampleArtworkTone } from '../../artwork/artworkTone';
import { neutralArtworkTone } from '../../artwork/useArtworkTone';
import { useCardHoverTone } from './useCardHoverTone';

vi.mock('../../artwork/artworkTone', () => ({ sampleArtworkTone: vi.fn() }));

const sample = vi.mocked(sampleArtworkTone);
const red = { hero: '#7a1f2b', pane: '#4f141c' };
const blue = { hero: '#1f4f7a', pane: '#16384f' };
// Tones are cached per image id for the whole file, so each test mounts its own pair of cards.
let nextId = 0;

const mount = () => {
  nextId += 2;
  const first = `/content/images/${String(nextId - 1).padStart(24, '0')}`;
  const second = `/content/images/${String(nextId).padStart(24, '0')}`;
  const tones = new Map([[`${first}/v1/96.webp`, red], [`${second}/v1/96.webp`, blue]]);
  sample.mockImplementation(async (url) => tones.get(url) ?? null);

  const Cards = () => (
    <div {...useCardHoverTone()}>
      <article data-artwork-src={first}><button type="button">First</button></article>
      <article data-artwork-src={second}><button type="button">Second</button></article>
      <article><button type="button">No artwork</button></article>
      <p>Section copy</p>
    </div>
  );
  const main = document.createElement('main');
  main.id = 'main-content';
  document.body.append(main);
  return { first, ...render(<Cards />, { container: main }) };
};

const paneTone = () => document.getElementById('main-content')?.style.getPropertyValue('--tone-color');
const settle = () => act(async () => { await vi.dynamicImportSettled(); });

/** jsdom has no PointerEvent, so set pointerType on a plain event that React still reads. */
const pointerOver = (target: Element, pointerType = 'mouse') => {
  const event = new MouseEvent('pointerover', { bubbles: true });
  Object.defineProperty(event, 'pointerType', { value: pointerType });
  fireEvent(target, event);
};

afterEach(() => {
  cleanup();
  vi.useRealTimers();
  document.body.innerHTML = '';
});

test('starts neutral, follows the hovered card, and returns to neutral after leaving the cards', async () => {
  vi.useFakeTimers();
  mount();
  expect(paneTone()).toBe(neutralArtworkTone.pane);

  pointerOver(screen.getByRole('button', { name: 'First' }));
  await settle();
  expect(paneTone()).toBe(red.pane);

  // Crossing the gap to the next card does not flash the neutral tone.
  pointerOver(screen.getByText('Section copy'));
  act(() => { vi.advanceTimersByTime(100); });
  pointerOver(screen.getByRole('button', { name: 'Second' }));
  await settle();
  expect(paneTone()).toBe(blue.pane);

  pointerOver(screen.getByRole('button', { name: 'No artwork' }));
  act(() => { vi.advanceTimersByTime(149); });
  expect(paneTone()).toBe(blue.pane);
  act(() => { vi.advanceTimersByTime(1); });
  expect(paneTone()).toBe(neutralArtworkTone.pane);
});

test('follows keyboard focus and keeps the focused card tone after the pointer leaves', async () => {
  vi.useFakeTimers();
  mount();
  const firstCard = screen.getByRole('button', { name: 'First' });

  act(() => firstCard.focus());
  await settle();
  expect(paneTone()).toBe(red.pane);

  pointerOver(screen.getByRole('button', { name: 'Second' }));
  await settle();
  expect(paneTone()).toBe(blue.pane);
  fireEvent.pointerLeave(firstCard.closest('div')!);
  act(() => { vi.advanceTimersByTime(150); });
  await settle();
  expect(paneTone()).toBe(red.pane);

  act(() => screen.getByRole('button', { name: 'No artwork' }).focus());
  act(() => { vi.advanceTimersByTime(150); });
  expect(paneTone()).toBe(neutralArtworkTone.pane);
});

test('ignores touch pointers and a tone that resolves after the pointer moved on', async () => {
  const { first } = mount();
  let finishFirst!: (tone: typeof red) => void;
  const resolveTone = sample.getMockImplementation()!;
  sample.mockImplementation((url) => url.startsWith(first)
    ? new Promise((resolve) => { finishFirst = resolve; })
    : resolveTone(url));

  pointerOver(screen.getByRole('button', { name: 'Second' }), 'touch');
  await settle();
  expect(paneTone()).toBe(neutralArtworkTone.pane);
  expect(sample).not.toHaveBeenCalled();

  pointerOver(screen.getByRole('button', { name: 'First' }));
  await settle();
  pointerOver(screen.getByRole('button', { name: 'Second' }));
  await settle();
  await act(async () => finishFirst(red));
  expect(paneTone()).toBe(blue.pane);
});

test('clears the main-pane tone on unmount and ignores samples that finish afterwards', async () => {
  const { unmount } = mount();
  let finish!: (tone: typeof red) => void;
  sample.mockImplementation(() => new Promise((resolve) => { finish = resolve; }));

  pointerOver(screen.getByRole('button', { name: 'First' }));
  await settle();
  unmount();
  expect(paneTone()).toBe('');
  await act(async () => finish(red));
  expect(paneTone()).toBe('');
});
